pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: the original owner who calls transferOwnership, and the intended newOwner
    function testFuzz_property(address originalOwner, address newOwner) public {
        // Keep addresses in the wide admissible domain but avoid zero address for clarity
        vm.assume(originalOwner != address(0));
        vm.assume(newOwner != address(0));

        // Make originalOwner be the contract owner initially by performing transferOwnership from deployer
        // The contract as deployed has owner == address(0) (default). We need to set owner to originalOwner.
        // Use vm.prank to act as the current owner (address(0)) and call transferOwnership to set owner to originalOwner.
        // Since address(0) cannot be msg.sender in a normal call, we instead first set owner to address(this) by calling
        // transferOwnership from the deploying test contract (which is address(this) here and is the deployer in setUp).
        // But c.owner was uninitialized; the contract's deployer is address(this) in setUp, so address(this) is the initial owner.

        // Confirm deployer (this) is able to set owner to originalOwner
        c.transferOwnership(originalOwner);
        // Now originalOwner is the owner; perform the ownership transfer from originalOwner to newOwner
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);

        // The universal property: after a successful transferOwnership(newOwner) call made by the current owner,
        // the contract's public owner() must equal the provided newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

